##
## Script for dumping state from a PCIe SS IP file with qsys-script for
## use by the OFS FIM.
##
## Do not use the --script argument. Instead, invoke qsys-script with a
## project and system-file, adding:
##
##     --cmd="source <path to this script>; emit_ip_cfg <generated .vh file name> <subsystem name>"
## e.g.:
##     --cmd="source pcie_ss_get_cfg.tcl; emit_ip_cfg pcie_ss_cfg.vh PCIE_SS"
##
## The subsystem name is included in each symbol written to the .vh file"
##

package require qsys

proc emit_ip_cfg {ofile_name ip_name} {
    set of [open $ofile_name w]

    puts $of "//"
    puts $of "// Generated by OFS script pcie_ss_get_cfg.tcl using qsys-script"
    puts $of "//"
    puts $of ""

    puts $of "`ifndef __OFS_FIM_IP_CFG_${ip_name}__"
    puts $of "`define __OFS_FIM_IP_CFG_${ip_name}__ 1"
    puts $of ""

    # Find the instance name in the IP's namespace (expecting "pcie_ss")
    set instances [get_instances]
    if { [llength $instances] != 1 } {
        send_message ERROR "Expected one instance in PCIe SS IP"
        exit 1
    }
    set inst [lindex $instances 0]

    # Find the largest PCIe core that is active.
    set width 0
    foreach p [get_instance_parameters $inst] {
        if { [regexp {core([0-9]+)_pf0_pci_type0_device_id_hwtcl} $p key w] } {
            set device_id [get_instance_parameter_value $inst "core${w}_pf0_pci_type0_device_id_hwtcl"]
            if { $device_id != 0 } {
                # Found an instance with a non-zero device ID
                if { $w > $width } {
                    set width $w
                }
            }
        }
    }

    if { $width == 0 } {
        send_message ERROR "Did not find an active PCIe width"
        exit 1
    }

    send_message INFO "PCIe x${width} is active"

    set pcie_num_links 0
    set interfaces [get_interfaces]

    # Create an associative array of all the active core's parameters. It's easier
    # to manipulate the array than to probe the IP repeatedly. After this, the
    # script will just use the $core() array. The "core<width>_" prefix is dropped
    # to simplify name matching.
    foreach p [get_instance_parameters $inst] {
        if { [string equal -nocase $p "top_topology_hwtcl"] } {
            # Change value to upper case and remove space
            set top_topology [string toupper [get_instance_parameter_value $inst $p]]
            regsub -all { +} $top_topology {_} top_topology

            # Extract the PCIe generation number from top topology (GenA_LXW)
            if { [regsub -all {.*GEN([0-9]+)_.*} $top_topology {\1} topology_pcie_gen] == 0 } {
                # Pattern match failed. Assume 4.
                set topology_pcie_gen 4
            }

            # Extract the number of links from top topology (GenA_LXW)
            if { [regsub -all {.*_+([0-9]+)X.*} $top_topology {\1} topology_num_links] == 0 } {
                # Pattern match failed. Assume 1.
                set topology_num_links 1
            }

            # Extract the link width from top topology (GenA_LXW)
            if { [regsub -all {.*X([0-9]+).*} $top_topology {\1} topology_link_width] == 0 } {
                # Pattern match failed. Assume 16.
                set topology_link_width 16
            }
        }

        # Number of links used by OFS, check every links pf0 device id
        if { [regexp {core([0-9]+)_pf0_pci_type0_device_id_hwtcl} $p key w] } {
            if { [get_instance_parameter_value $inst "core${w}_pf0_pci_type0_device_id_hwtcl"] == $device_id } {
                # increment pcie links used by OFS
                incr pcie_num_links
            }
        }

        # Tile name
        if { [string equal -nocase $p "tile"] } {
            set tile_name [get_instance_parameter_value $inst $p]
            set tile_name_macro [string map {- _} [string toupper $tile_name]]
        }

        # Native endpoint mode?
        if { [string equal -nocase $p "virtual_rp_ep_mode_hwtcl"] } {
            set m [get_instance_parameter_value $inst $p]
            if { [string first "Native Endpoint" $m] != -1 } {
                set pcie_ss_rp_ep_mode "NATIVE_EP"
            }
        }

        # Functional mode, original PCIe SS ("AXI-ST Data Mover" or "Power User")
        if { [string equal -nocase $p "pcie_ss_func_mode_hwtcl"] } {
            set fm [get_instance_parameter_value $inst $p]
            if { [string first "Data Mover" $fm] != -1 } {
                set pcie_ss_func_mode "DM"
            } elseif { [string first "Power User" $fm] != -1 } {
                set pcie_ss_func_mode "PU"
            }
        }

        # Pipe mode simulation?
        # pipemode_sim_hwtcl used by Agilex 5 IP
        if { [string equal -nocase $p "pipemode_sim_hwtcl"] } {
            set m [get_instance_parameter_value $inst $p]
            if { $m } {
                set pcie_ss_pipe_mode 1
            }
        }
        # pipemode_sim_ed_hwtcl used by Agilex 7 AXI-S IP
        if { [string equal -nocase $p "pipemode_sim_ed_hwtcl"] } {
            set m [get_instance_parameter_value $inst $p]
            if { $m } {
                # Some IP has the PIPE mode flag but doesn't actually support PIPE
                # mode. Check whether an interface matching a pipe mode is present.
                foreach p $interfaces {
                    if { [string first "txpipe" $p] != -1 || [string first "fastp_pcie" $p] != -1 } {
                        set pcie_ss_pipe_mode 1
                        break
                    }
                }
            }
        }

        if { [regexp "^core${width}_(.*)" $p match key] } {
            set core([string tolower $key]) [get_instance_parameter_value $inst $p]
        }
    }


    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_IS_${tile_name_macro} 1"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_TILE_NAME \"${tile_name}\""
    puts $of ""

    puts $of "// PCIe SS Topology"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_${top_topology} 1"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PCIE_GEN ${topology_pcie_gen}"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PCIE_GEN_IS_${topology_pcie_gen} 1"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PCIE_LINK_WIDTH ${topology_link_width}"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PCIE_LINK_WIDTH_IS_${topology_link_width} 1"
    puts $of "// Number of links active inside the PCIe SS"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_PHYS_LINKS ${topology_num_links}"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_PHYS_LINKS_IS_${topology_num_links} 1"
    puts $of "// Number of links used by the OFS FIM"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_LINKS ${pcie_num_links}"
    set total_num_lanes [expr $pcie_num_links * $topology_link_width]
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_TOTAL_NUM_LANES ${total_num_lanes}"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_TOTAL_NUM_LANES_IS_${total_num_lanes} 1"
    for {set idx 0} { $idx < $pcie_num_links } {incr idx} {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_EN_LINK_${idx} 1"
    }

    puts $of ""

    puts $of "// PCIe SS Interface"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_FUNC_MODE \"${pcie_ss_func_mode}\""
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_FUNC_MODE_IS_${pcie_ss_func_mode} 1"
    if { ${pcie_ss_func_mode} != "DM" } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PORT_MODE \"${pcie_ss_rp_ep_mode}\""
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PORT_MODE_IS_${pcie_ss_rp_ep_mode} 1"
    }

    if { [info exists core(header_scheme_hwtcl)] } {
        set hdr [string map {- _} [string toupper $core(header_scheme_hwtcl)]]
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HDR_SCHEME \"${hdr}\""
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HDR_SCHEME_IS_${hdr} 1"
    } else {
        # Assume in-band if not defined
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HDR_SCHEME \"IN_BAND\""
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HDR_SCHEME_IS_IN_BAND 1"
    }

    if { [info exists core(dwidth_byte_hwtcl)] } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_DWIDTH_BYTE $core(dwidth_byte_hwtcl)"
    }
    if { [info exists core(num_of_seg)] } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_SEG ${core(num_of_seg)}"
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_SEG_IS_${core(num_of_seg)} 1"
    } else {
        # Assume 1 if not set
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_SEG 1"
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_SEG_IS_1 1"
    }

    if { [info exists pcie_ss_pipe_mode] } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_IS_PIPE_MODE_SIM 1"
    }

    # Tiles have interface differences, such as tuser fields for side-band headers.
    # Generate macros indicating ports that are present.
    puts $of ""
    puts $of "// PCIe SS top-level interface ports"
    foreach p [lsort $interfaces] {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HAS_[string toupper ${p}] 1"


        #
        # The macros below were the original ports checked by the script
        # and mapped to names without the leading "p0_". At the time, the script
        # didn't have the line above that emits a HAS macro for every interface.
        # The macros below are kept to avoid breaking existing RTL.
        #

        # All RX/TX TUSER ports, e.g. as OFS_FIM_IP_CFG_PCIE_SS_HAS_TX_TUSER_LAST_SEGMENT
        if { [regexp {p0_.*_st_([rt]x_tuser.*)} $p key port] } {
            puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HAS_[string toupper ${port}] 1"
        }
        # RX/TX credit port, e.g. OFS_FIM_IP_CFG_PCIE_SS_HAS_RXCRDT
        if { [regexp {p0_st_([rt]xcrdt)} $p key port] } {
            puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HAS_[string toupper ${port}] 1"
        }
    }

    # Does the RX interface have tready?
    set st_rx_idx [lsearch -glob $interfaces "*_st_rx"]
    if { $st_rx_idx != -1 } {
        set st_rx_ifc [lindex $interfaces $st_rx_idx]
        if { [lsearch -glob [get_interface_ports $st_rx_ifc] "*_tready"] != -1 } {
            puts $of "`define OFS_FIM_IP_CFG_${ip_name}_ST_RX_HAS_TREADY 1"
        } else {
            puts $of "// No tready in st_rx (OFS_FIM_IP_CFG_${ip_name}_ST_RX_HAS_TREADY not set)"
        }
    }

    # Does the FLR completion interface have a tready output?
    set flrcmpl_idx [lsearch -glob $interfaces "*_st_flrcmpl"]
    if { $flrcmpl_idx != -1 } {
        set flrcmpl_ifc [lindex $interfaces $flrcmpl_idx]
        if { [lsearch -glob [get_interface_ports $flrcmpl_ifc] "*_tready"] != -1 } {
            puts $of "`define OFS_FIM_IP_CFG_${ip_name}_FLRCMPL_HAS_TREADY 1"
        } else {
            puts $of "// No tready in flrcmpl (OFS_FIM_IP_CFG_${ip_name}_FLRCMPL_HAS_TREADY not set)"
        }
    }

    # Configuration extension bus enabled?
    if { [info exists core(ceb_en_hwtcl)] && $core(ceb_en_hwtcl) } {
        puts $of ""
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HAS_CEB 1"
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_CEB_PF_STD_NEXT_DW [format 'h%x $core(ceb_pf_std_cap_last_ptr_hwtcl)]"
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_CEB_PF_EXT_NEXT_DW [format 'h%x $core(ceb_pf_ext_cap_last_ptr_hwtcl)]"
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_CEB_VF_STD_NEXT_DW [format 'h%x $core(ceb_vf_std_cap_last_ptr_hwtcl)]"
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_CEB_VF_EXT_NEXT_DW [format 'h%x $core(ceb_vf_ext_cap_last_ptr_hwtcl)]"
        puts $of ""
    } else {
        puts $of "// No configuration extension bus (OFS_FIM_IP_CFG_${ip_name}_HAS_CEB not set)"
    }

    # Sorted completions? Meaningful only in DM mode.
    if { [info exists core(cpl_reordering_en_hwtcl)] && $core(cpl_reordering_en_hwtcl) } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_HAS_CPL_REORDER 1"
    } else {
        puts $of "// No completion reordering (OFS_FIM_IP_CFG_${ip_name}_HAS_CPL_REORDER not set)"
    }

    puts $of ""

    # Look for active PFs and VFs
    puts $of "//"
    puts $of "// The OFS_FIM_IP_CFG_<ip_name>_PF<n>_ACTIVE macro will be defined iff the"
    puts $of "// PF is active. The value does not have to be tested."
    puts $of "//"
    puts $of "// For each active PF<n>, OFS_FIM_IP_CFG_<ip_name>_PF<n>_NUM_VFS will be"
    puts $of "// defined iff there are VFs associated with the PF."
    puts $of "//"
    puts $of ""

    set num_pfs 0
    set max_pf_num 0
    set total_num_vfs 0
    set max_vfs_per_pf 0

    # Construct two arrays. pf_active_arr entries are 0 or 1, indicating whether
    # the PF number is enabled. num_vfs_arr is the number of VFs associated with
    # a PF index.
    set pf_active_arr(0) 0
    set num_vfs_arr(0) 0

    set ats_cap_enabled 0
    set prs_cap_enabled 0
    set pasid_cap_enabled 0

    # Loop through all PFs. This loop is set up to support sparse PF numbering,
    # though the PCIe SS configuration forces dense PF numbering.
    for { set pf_num 0 } { $pf_num < $core(total_pf_count_hwtcl) } { incr pf_num } {
        set pf_active_arr($pf_num) 0
        set num_vfs_arr($pf_num) 0

        # PF active?
        if { $core(pf${pf_num}_pci_type0_device_id_hwtcl) > 0 } {
            set pf_active_arr($pf_num) 1
            set max_pf_num $pf_num
            incr num_pfs 1
            puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_ACTIVE 1"
            puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_BAR0_ADDR_WIDTH $core(pf${pf_num}_bar0_address_width_hwtcl)"

            # Define capability macros only when enabled
            if { $core(virtual_pf${pf_num}_ats_cap_enable_hwtcl) > 0 } {
                puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_ATS_CAP 1"
                set ats_cap_enabled 1
            }
            if { $core(virtual_pf${pf_num}_prs_ext_cap_enable_hwtcl) > 0 } {
                puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_PRS_CAP 1"
                set prs_cap_enabled 1
            }
            if { $core(virtual_pf${pf_num}_pasid_cap_enable_hwtcl) > 0 } {
                puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_PASID_CAP 1"
                set pasid_cap_enabled 1
            }

            # VFs active?
            set num_vfs $core(pf${pf_num}_vf_count_hwtcl)
            if { $num_vfs > 0 } {
                set num_vfs_arr($pf_num) $num_vfs
                puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_NUM_VFS ${num_vfs}"
                puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_VF_BAR0_ADDR_WIDTH $core(pf${pf_num}_sriov_vf_bar0_address_width_hwtcl)"
                incr total_num_vfs $num_vfs
                if { $num_vfs > $max_vfs_per_pf } {
                    set max_vfs_per_pf $num_vfs
                }

                if { $core(pf${pf_num}_vf_ats_cap_enable_hwtcl) > 0 } {
                    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PF${pf_num}_VF_ATS_CAP 1"
                }
            }

            puts $of ""
        }
    }

    puts $of ""
    puts $of "//"
    puts $of "// The macros below represent the raw PF/VF configuration above in"
    puts $of "// ways that are easier to process in SystemVerilog loops."
    puts $of "//"
    puts $of ""

    puts $of "// Total number of PFs, not necessarily dense (see MAX_PF_NUM)"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_PFS ${num_pfs}"
    puts $of "// Total number of VFs across all PFs"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_TOTAL_NUM_VFS ${total_num_vfs}"
    puts $of "// Largest active PF number"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MAX_PF_NUM ${max_pf_num}"
    puts $of "// Largest number of VFs associated with a single PF"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MAX_VFS_PER_PF ${max_vfs_per_pf}"
    puts $of ""

    puts $of "// Vector indicating enabled PFs (1 if enabled) with"
    puts $of "// index range 0 to OFS_FIM_IP_CFG_${ip_name}_MAX_PF_NUM"
    puts -nonewline $of "`define OFS_FIM_IP_CFG_${ip_name}_PF_ENABLED_VEC "
    for { set i 0 } { $i <= $max_pf_num } { incr i } {
        if { $i > 0 } { puts -nonewline $of ", " }
        puts -nonewline $of $pf_active_arr($i)
    }
    puts $of ""

    puts $of "// Vector with the number of VFs indexed by PF"
    puts -nonewline $of "`define OFS_FIM_IP_CFG_${ip_name}_NUM_VFS_VEC "
    for { set i 0 } { $i <= $max_pf_num } { incr i } {
        if { $i > 0 } { puts -nonewline $of ", " }
        puts -nonewline $of $num_vfs_arr($i)
    }
    puts $of ""

    ## MSI-X - extract configuration into lists
    set msix_table_size_list {0 0 0 0 0 0 0 0}
    set msix_table_offset_list {0 0 0 0 0 0 0 0}
    set msix_table_bar_list {0 0 0 0 0 0 0 0}
    set msix_table_bar_log2_size_list {0 0 0 0 0 0 0 0}
    set msix_pba_offset_list {0 0 0 0 0 0 0 0}
    set msix_pba_bar_list {0 0 0 0 0 0 0 0}
    set msix_vf_table_size_list {0 0 0 0 0 0 0 0}
    set msix_vf_table_offset_list {0 0 0 0 0 0 0 0}
    set msix_vf_table_bar_list {0 0 0 0 0 0 0 0}
    set msix_vf_table_bar_log2_size_list {0 0 0 0 0 0 0 0}
    set msix_vf_pba_offset_list {0 0 0 0 0 0 0 0}
    set msix_vf_pba_bar_list {0 0 0 0 0 0 0 0}
    for { set pf_num 0 } { $pf_num <= $max_pf_num } { incr pf_num } {
        if { $pf_active_arr($pf_num) && $core(virtual_pf${pf_num}_msix_enable_user_hwtcl) } {
            # Convert table encoding to actual size (add 1)
            set msix_table_size_list [lreplace $msix_table_size_list $pf_num $pf_num [expr $core(pf${pf_num}_pci_msix_table_size_hwtcl) + 1]]
            # Convert offsets to true BAR byte offset
            set msix_table_offset_list [lreplace $msix_table_offset_list $pf_num $pf_num [format 'h%x [expr int($core(pf${pf_num}_pci_msix_table_offset_hwtcl)) << 3]]]
            set b $core(pf${pf_num}_pci_msix_bir_hwtcl)
            set msix_table_bar_list [lreplace $msix_table_bar_list $pf_num $pf_num $b]
            # Size of the BAR (first check that the BAR is enabled)
            if { $core(pf${pf_num}_bar${b}_type_user_hwtcl) != 0 } {
                set msix_table_bar_log2_size_list [lreplace $msix_table_bar_log2_size_list $pf_num $pf_num $core(pf${pf_num}_bar${b}_address_width_user_hwtcl)]
            }
            set msix_pba_offset_list [lreplace $msix_pba_offset_list $pf_num $pf_num [format 'h%x [expr int($core(pf${pf_num}_pci_msix_pba_offset_hwtcl)) << 3]]]
            set msix_pba_bar_list [lreplace $msix_pba_bar_list $pf_num $pf_num $core(pf${pf_num}_pci_msix_pba_hwtcl)]

            if { $num_vfs_arr($pf_num) && $core(virtual_pf${pf_num}_exvf_msix_cap_enable_hwtcl) } {
                set msix_vf_table_size_list [lreplace $msix_vf_table_size_list $pf_num $pf_num [expr $core(exvf_msix_tablesize_pf${pf_num}) + 1]]
                set msix_vf_table_offset_list [lreplace $msix_vf_table_offset_list $pf_num $pf_num [format 'h%x [expr int($core(exvf_msixtable_offset_pf${pf_num})) << 3]]]
                set b $core(exvf_msixtable_bir_pf${pf_num})
                set msix_vf_table_bar_list [lreplace $msix_vf_table_bar_list $pf_num $pf_num $b]
                # Size of the BAR (first check that the BAR is enabled)
                if { $core(pf${pf_num}_sriov_vf_bar${b}_type_hwtcl) != 0 } {
                    set msix_vf_table_bar_log2_size_list [lreplace $msix_vf_table_bar_log2_size_list $pf_num $pf_num $core(pf${pf_num}_sriov_vf_bar${b}_address_width_hwtcl)]
                }
                set msix_vf_pba_offset_list [lreplace $msix_vf_pba_offset_list $pf_num $pf_num [format 'h%x [expr int($core(exvf_msixpba_offset_pf${pf_num})) << 3]]]
                set msix_vf_pba_bar_list [lreplace $msix_vf_pba_bar_list $pf_num $pf_num $core(exvf_msixpba_bir_pf${pf_num})]
            }
        }
    }
    puts $of ""
    puts $of ""
    puts $of "//"
    puts $of "// MSI-X information: vectors, indexed by PF number"
    puts $of "//"
    puts $of "// PF table sizes (true size, not encoded size-1)"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_PF_TABLE_SIZE_VEC [join $msix_table_size_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_PF_TABLE_OFFSET_VEC [join $msix_table_offset_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_PF_TABLE_BAR_VEC [join $msix_table_bar_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_PF_TABLE_BAR_LOG2_SIZE_VEC [join $msix_table_bar_log2_size_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_PF_PBA_OFFSET_VEC [join $msix_pba_offset_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_PF_PBA_BAR_VEC [join $msix_pba_bar_list ", "]"
    puts $of "// VF table sizes (true size, not encoded size-1)"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_VF_TABLE_SIZE_VEC [join $msix_vf_table_size_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_VF_TABLE_OFFSET_VEC [join $msix_vf_table_offset_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_VF_TABLE_BAR_VEC [join $msix_vf_table_bar_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_VF_TABLE_BAR_LOG2_SIZE_VEC [join $msix_vf_table_bar_log2_size_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_VF_PBA_OFFSET_VEC [join $msix_vf_pba_offset_list ", "]"
    puts $of "`define OFS_FIM_IP_CFG_${ip_name}_MSIX_VF_PBA_BAR_VEC [join $msix_vf_pba_bar_list ", "]"
    puts $of ""

    puts $of ""
    puts $of "//"
    puts $of "// If ATS, PRS or PASID is enabled on at least one PF the following"
    puts $of "// macros will be defined here, one per feature:"
    puts $of "//   OFS_FIM_IP_CFG_${ip_name}_ATS_CAP"
    puts $of "//   OFS_FIM_IP_CFG_${ip_name}_PRS_CAP"
    puts $of "//   OFS_FIM_IP_CFG_${ip_name}_PASID_CAP"
    puts $of "//"
    if { $ats_cap_enabled > 0 } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_ATS_CAP 1"
    }
    if { $prs_cap_enabled > 0 } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PRS_CAP 1"
    }
    if { $pasid_cap_enabled > 0 } {
        puts $of "`define OFS_FIM_IP_CFG_${ip_name}_PASID_CAP 1"
    }

    # Emit ATS/PRS/PASID configuration as vectors, indexed by PF. These may
    # be used by modules that operate on multiplexed TLP streams and maintain
    # per-function state.
    puts $of ""
    puts $of "// Vector indicating whether ATS is enabled, indexed by PF"
    puts -nonewline $of "`define OFS_FIM_IP_CFG_${ip_name}_ATS_CAP_VEC "
    puts $of [join [get_cfg_enable_pf_vec core $max_pf_num virtual_pf _ats_cap_enable_hwtcl] ", "]

    puts $of "// Vector indicating whether ATS is enabled for VFs, indexed by PF"
    puts -nonewline $of "`define OFS_FIM_IP_CFG_${ip_name}_VF_ATS_CAP_VEC "
    # Entries in the ATS VF vector are true if VFs and ATS are enabled
    set vf_ena [get_cfg_enable_pf_vec core $max_pf_num pf _vf_count_hwtcl]
    set vf_ats [get_cfg_enable_pf_vec core $max_pf_num pf _vf_ats_cap_enable_hwtcl]
    set v {}
    foreach {ena} $vf_ena {ats} $vf_ats {
        lappend v [expr {$ena && $ats}]
    }
    puts $of [join $v ", "]

    puts $of "// Vector indicating whether PRS is enabled, indexed by PF"
    puts -nonewline $of "`define OFS_FIM_IP_CFG_${ip_name}_PRS_CAP_VEC "
    puts $of [join [get_cfg_enable_pf_vec core $max_pf_num virtual_pf _prs_ext_cap_enable_hwtcl] ", "]

    puts $of "// Vector indicating whether PASID is enabled, indexed by PF"
    puts -nonewline $of "`define OFS_FIM_IP_CFG_${ip_name}_PASID_CAP_VEC "
    puts $of [join [get_cfg_enable_pf_vec core $max_pf_num virtual_pf _pasid_cap_enable_hwtcl] ", "]

    puts $of ""
    puts $of "`endif // `ifndef __OFS_FIM_IP_CFG_${ip_name}__"

    close $of
}


##
## Return a list with one entry per PF. Entries in the returned list are
## either 0 or 1 depending on whether the key ${name_prefix}<pf_num>${name_suffix}
## has a non-zero value in $core()..
##
proc get_cfg_enable_pf_vec {coreRef max_pf_num name_prefix name_suffix} {
    upvar $coreRef core
    set v {}

    for { set pf_num 0 } { $pf_num <= $max_pf_num } { incr pf_num } {
        lappend v [expr ($core(${name_prefix}${pf_num}${name_suffix}) > 0)]
    }

    return $v
}

ofs-common/scripts/common/syn/report_tim.text:
# Copyright 2020 Intel Corporation
# SPDX-License-Identifier: MIT

##
## Invoke from quartus_sta -t or as a hook at the end of quartus_sta.
##
## Generate a timing report in output_files/timing_report. When
## output_files/timing_report/clocks.sta.fail.summary is empty there are
## no timing violations.
##
## This script may either be sourced with a timing netlist already
## created or run stand-alone with quartus_sta. Logic at the bottom
## detects the mode.
##

# Add tcl_lib subdirectory of this script to package search path
lappend auto_path [file join [pwd] [file dirname [info script]] tcl_lib]
# OFS script for parsing command line options
package require options


#************************************************
# Description: Print the HELP info
#************************************************
proc PrintHelp {} {
   puts "This script generates detailed timing report for the given project in output_files/timing_report"
   puts "Usage: report_timing.tcl <option>.."
   puts "Supported options:"
   puts "    --project <project>         "
   puts "    --revision <revision>       "
}


# Write clock summary to open file handle $ofile
proc emitClockSummaryInfo {ofile corner domain type} {
  set name [lindex $domain 0]
  set slack [lindex $domain 1]
  set keeper_tns [lindex $domain 2]

  puts $ofile "Type  : ${corner} ${type} '${name}'"
  puts $ofile "Slack : ${slack}"
  puts $ofile "TNS   : ${keeper_tns}"
  puts $ofile ""
}


proc subReportTiming {project revision} {
  if [file exists output_files/timing_report] {
    file delete -force -- output_files/timing_report
  }

  report_clocks -file "output_files/timing_report/clocks.rpt"

  set pass_file [open "output_files/timing_report/clocks.sta.pass.summary" w]
  set fail_file [open "output_files/timing_report/clocks.sta.fail.summary" w]

  set operating_conditions [get_available_operating_conditions]
  foreach corner $operating_conditions {
    set_operating_conditions $corner
    # User clock frequency changes may update the timing. Apply the time
    # borrowing computed for the target frequency by setting dynamic_borrow.
    update_timing_netlist -dynamic_borrow

    set report_type_list {setup hold recovery removal mpw}
    foreach type $report_type_list {
      set report_name "output_files/timing_report/${revision}_${corner}_${type}.rpt"
      set domain_list [get_clock_domain_info -${type}]
      foreach domain $domain_list {
        set name [lindex $domain 0]
        set slack [lindex $domain 1]

        if {$slack >= 0} {
          emitClockSummaryInfo $pass_file $corner $domain $type
        } else {
          emitClockSummaryInfo $fail_file $corner $domain $type

          if {$type != "mpw"} {
            report_timing -to_clock $name -${type} -show_routing -npaths 20 -file $report_name -append
          } else {
            report_min_pulse_width -nworst 20 -file $report_name -append
          }
        }
      }
    }
  }

  close $pass_file
  close $fail_file
}

#************************************************
# Description: Entry point of TCL post processing
#************************************************
proc main {} {
  # Run as the top level script. Open a project.
  if { [::options::ParseCMDArguments {--project --revision}] == -1 } {
    PrintHelp
    return -1
  }

  set project $::options::optionMap(--project)
  set revision $::options::optionMap(--revision)

  project_open -revision $revision $project
  create_timing_netlist
  read_sdc

  subReportTiming $project $revision

  delete_timing_netlist
  project_close
}

proc from_sta {} {
  # Run from another script with a project open
  set project [get_current_project]
  set revision [get_current_revision]

  post_message "Running OFS report_timing.tcl" \
    -submsgs [list "Project: ${project}" "Revision: ${revision}"]

  subReportTiming $project $revision
}

if { [info script] eq $::argv0 } {
  main
} else {
  from_sta
}

ofs-common/scripts/common/syn/tcl_lib/op.text:
# Copyright 2022 Intel Corporation
# SPDX-License-Identifier: MIT

##
## Package to map argc/argv to ::options:optionMap.
##
## Call ParseCMDArguments, passing a list of the option names expected.
## On return, option values are in optionMap.
##

namespace eval options {
  variable optionMap

  # Export proc to be invoked that processes argc/argv
  namespace export ParseCMDArguments

  set version 1.0
  set MyDescription "HelloWorld"

  # Path of the script
  variable dir [file join [pwd] [file dirname [info script]]]
}


##
## Parse the input arguments to the script. Both required_args
## and optional_args are lists of argument names. An error
## is returned if any of the required_args is not set. An
## error is also returned if an argument name is not in either
## list.
##
## On return, optionMap is indexed by argument names. Optional
## arguments will be defined only if they are found on the
## command line.
##
proc ::options::ParseCMDArguments {required_args {optional_args {}}} {
  global argv
  global argc

  if { [info exists ::options::optionMap] } {
    array unset ::options::optionMap
  }
  array set ::options::optionMap {}

  # Expect these options
  foreach a $required_args {
    set singleOptionMap($a) -1
  }

  set success 1
  set i 0

  while { ($i < $argc) && ($success==1) } {
    set arg [lindex $argv $i]
    incr i

    set optList [split $arg "="]
    set opt [lindex $optList 0]

    # Is opt an optional argument? If so, add the option name to the map.
    if { ![info exists singleOptionMap($opt)] && [lsearch $optional_args $opt] >= 0} {
      set singleOptionMap($opt) -1
    }

    if [info exists singleOptionMap($opt)] {
      if { $singleOptionMap($opt) == -1 } {
        if { [llength $optList] < 2 } {
          set success 0
          puts "Error: No value is specified for option $opt"
        } elseif { [llength $optList] > 2 } {
          set success 0
          puts "Error: Illegal option found \"$arg\"."
        } else {
          set optValue [lindex $optList 1]
          if [string equal $optValue ""] {
            set success 0
            puts "Error: No value is specified for option $opt"
          } else {
            set ::options::optionMap($opt) $optValue
          }
        }
      } else {
        if { [llength $optList] == 1 } {
          set ::options::optionMap($arg) 1
        } else {
          set success 0
          puts "Error: Illegal option found \"$arg\"."
        }
      }
    } else {
      set success 0
      puts "Error: $arg is not a valid option."
    }
  }

  if { $success == 1 } {
    foreach opt [array names singleOptionMap] {
      if { $singleOptionMap($opt) == -1 } {
        if { ![info exists ::options::optionMap($opt)] } {
          puts "Error: Missing $opt option."
          set success 0
        }
      }
    }
  }

  if {$success != 1 } {
    return -1
  } 
  return 0
}

package provide options $options::version

ofs-common/scripts/common/syn/user_clock.text:
# Copyright 2020-2024 Intel Corporation
# SPDX-License-Identifier: MIT

##
## Invoke from quartus_sta -t or as a hook at the end of quartus_sta.
##
## When the user clock is in "auto" mode, compute the achieved Fmax.
## The chosen user clock frequency is written to
## output_files/user_clock_freq.txt.
##
## This script may either be sourced with a timing netlist already
## created or run stand-alone with quartus_sta. Logic at the bottom
## detects the mode.
##

# Required packages
package require ::quartus::project
package require ::quartus::report
package require ::quartus::flow

# Add tcl_lib subdirectory of this script to package search path
lappend auto_path [file join [pwd] [file dirname [info script]] tcl_lib]
# OFS script for parsing command line options
package require options


# Load state into userClocks namespace
source ofs_partial_reconfig/user_clock_defs.tcl


proc compute_uclk {project_name revision_name} {
    set jitter_compensation 0.01

    load_report $revision_name

    delete_computed_user_clocks_file

    # get device speedgrade
    set part_name [get_global_assignment -name DEVICE]
    post_message "Device part name is $part_name"
    set report [report_part_info $part_name]
    regexp {Speed Grade.*$} $report speedgradeline
    regexp {(\d+)} $speedgradeline speedgrade
    if { $speedgrade < 1 || $speedgrade > 8 } {
        post_message "Speedgrade is $speedgrade and not in the range of 1 to 8"
        post_message "Terminating post-flow script"
        return TCL_ERROR
    }
    post_message "Speedgrade is $speedgrade"

    set need_timing_update 0
    set json_uclk_freqs [get_afu_json_user_clock_freqs]

    if {[uclk_freq_is_auto $json_uclk_freqs]} {
        post_message "User clocks auto mode: computing FMax"

        if {[llength $json_uclk_freqs] == 2 &&
            0 == [string compare -nocase -length 4 "auto" [lindex $json_uclk_freqs 0]] &&
            0 == [string compare -nocase -length 4 "auto" [lindex $json_uclk_freqs 1]]} {
            # Both high and low clocks are in auto mode
            if {! [uclk_used_in_afu $::userClocks::u_clk_name]} {
                set json_uclk_freqs [lreplace $json_uclk_freqs 1 1 0]
                post_message "User clock high is not used by the AFU. Allowing full range of the low frequency clock."
            }
        }

        # Get the achieved frequencies for each clock
        set x [get_user_clks_and_fmax $::userClocks::u_clkdiv2_name $::userClocks::u_clk_name $jitter_compensation]
        # Construct a list of just frequencies (low then high)
        set uclk_freqs_actual [list [lindex $x 0] [lindex $x 2]]

        # Choose uclk frequencies, based on the original JSON constraints and
        # the achieved frequencies.
        set uclk_freqs [uclk_pick_aligned_freqs $json_uclk_freqs $uclk_freqs_actual $::userClocks::u_clk_fmax]

        # Write chosen frequencies to a file, which will be used both by the
        # next timing analysis phase and by the packager.
        save_computed_user_clocks $uclk_freqs
        set need_timing_update 1
    } else {
        post_message "User clocks not in auto mode"

        # Canonicalize clocks in case only one was specified
        if {[llength $json_uclk_freqs] == 2} {
            if {[lindex $json_uclk_freqs 0] == 0} {
                lset json_uclk_freqs 0 [expr {[lindex $json_uclk_freqs 1] / 2.0}]
            }
            if {[lindex $json_uclk_freqs 1] == 0} {
                lset json_uclk_freqs 1 [expr {[lindex $json_uclk_freqs 0] * 2}]
            }

            save_computed_user_clocks $json_uclk_freqs
        }
    }

    return $need_timing_update
}


#
# Check whether a user clock is used by the AFU region in the design.
#
proc uclk_used_in_afu {uclk_name} {
    set uclk [get_clocks -include_generated_clocks $uclk_name]

    # We expect a single afu_main(), but we may as well check the
    # returned list of instances.
    foreach afu_main [get_entity_instances -nowarn afu_main] {
        # Is there any register inside afu_main() clocked by uclk?
        set paths [get_timing_paths -to_clock $uclk -to [get_registers "{$afu_main|*}"] -npaths 1 -setup]
        if { [get_collection_size $paths] > 0 } {
            return 1
        }
    }

    # Clock not used
    return 0
}


# Return values: [retval panel_id row_index]
#   panel_id and row_index are only valid if the query is successful
# retval:
#    0: success
#   -1: not found
#   -2: panel not found (could be report not loaded)
#   -3: no rows found in panel
#   -4: multiple matches found
proc find_report_panel_row { panel_name col_index string_op string_pattern } {
    if {[catch {get_report_panel_id $panel_name} panel_id] || $panel_id == -1} {
        return -2;
    }

    if {[catch {get_number_of_rows -id $panel_id} num_rows] || $num_rows == -1} {
        return -3;
    }

    # Search for row match.
    set found 0
    set row_index -1;

    for {set r 1} {$r < $num_rows} {incr r} {
        if {[catch {get_report_panel_data -id $panel_id -row $r -col $col_index} value] == 0} {


            if {[string $string_op $string_pattern $value]} {
                if {$found == 0} {

                    # If multiple rows match, return the first
                    set row_index $r

                }
                incr found
            }

        }
    }

    if {$found > 1} {return [list -4 $panel_id $row_index]}
    if {$row_index == -1} {return -1}

    return [list 0 $panel_id $row_index]
}


# get_fmax_from_report: Determines the fmax for the given clock. The fmax value returned
# will meet all timing requirements (setup, hold, recovery, removal, minimum pulse width)
# across all corners.  The return value is a 2-element list consisting of the
# fmax and clk name
proc get_fmax_from_report { clkname required jitter_compensation} {
    # Find the clock period.
    set result [find_report_panel_row "Timing Analyzer||Clocks" 0 match $clkname]
    set retval [lindex $result 0]

    if {$retval == -1} {
        if {$required == 1} {
           error "Error: Could not find clock: $clkname"
        } else {
           post_message -type warning "Could not find clock: $clkname.  Clock is not required assuming 10 GHz and proceeding."
           return [list 10000 $clkname]
        }
    } elseif {$retval < 0} {
        error "Error: Failed search for clock $clkname (error $retval)"
    }

    # Update clock name to full clock name ($clkname as passed in may contain wildcards).
    set panel_id [lindex $result 1]
    set row_index [lindex $result 2]
    set clkname [get_report_panel_data -id $panel_id -row $row_index -col 0]
    set clk_period [get_report_panel_data -id $panel_id -row $row_index -col 2]

    post_message "Clock $clkname"
    post_message "  Period: $clk_period"

    # Determine the most negative slack across all relevant timing metrics (setup, recovery, minimum pulse width)
    # and across all timing corners. Hold and removal metrics are not taken into account
    # because their slack values are independent on the clock period (for kernel clocks at least).
    #
    # Paths that involve both a posedge and negedge of the kernel clocks are not handled properly (slack
    # adjustment needs to be doubled).
    set timing_metrics [list "Setup" "Recovery" "Minimum Pulse Width"]
    set timing_metric_colindex [list 1 3 5 ]
    set timing_metric_required [list 1 0 0]
    set wc_slack $clk_period
    set has_slack 0
    set fmax_from_summary 5000.0

    # Find the "Fmax Summary" numbers reported in Quartus.  This may not
    # account for clock transfers but it does account for pos-to-neg edge same
    # clock transfers.  Whatever we calculate should be less than this.
    set fmax_panel_name "Timing Analyzer||*Fmax Summary"
    foreach panel_name [get_report_panel_names] {
      if {[string match $fmax_panel_name $panel_name] == 1} {
        set result [find_report_panel_row $panel_name 2 equal $clkname]
        set retval [lindex $result 0]
        if {$retval == 0} {
          set restricted_fmax_field [get_report_panel_data -id [lindex $result 1] -row [lindex $result 2] -col 1]
          regexp {([0-9\.]+)} $restricted_fmax_field restricted_fmax
          if {$restricted_fmax < $fmax_from_summary} {
            set fmax_from_summary $restricted_fmax
          }
        }
      }
    }
    post_message "  Restricted Fmax from STA: $fmax_from_summary"

    # Find the worst case slack across all corners and metrics
    foreach metric $timing_metrics metric_required $timing_metric_required col_ndx $timing_metric_colindex {
      set panel_name "Timing Analyzer||Multicorner Timing Analysis Summary"
      set panel_id [get_report_panel_id $panel_name]
      set result [find_report_panel_row $panel_name 0 equal " $clkname"]
      set retval [lindex $result 0]

      if {$retval == -1} {
        if {$required == 1 && $metric_required == 1} {
          error "Error: Could not find clock: $clkname"
        }
      } elseif {$retval < 0 && $retval != -4 } {
        error "Error: Failed search for clock $clkname (error $retval)"
      }

      if {$retval == 0 || $retval == -4} {
        set slack [get_report_panel_data -id [lindex $result 1] -row [lindex $result 2] -col $col_ndx ]
        post_message "    $metric slack: $slack"
        if {$slack != "N/A"} {
          if {$metric == "Setup" || $metric == "Recovery"} {
            set has_slack 1
            if {$metric == "Recovery"} {
              set normalized_slack [ expr $slack / 4.0 ]
              post_message "    normalized $metric slack: $normalized_slack"
              set slack $normalized_slack
            }
          }
        }
        # Keep track of the most negative slack.
        if {$slack < $wc_slack} {
          set wc_slack $slack
          set wc_metric $metric
        }
      }
    }

    if {$has_slack == 1} {
        # Adjust the clock period to meet the worst-case slack requirement.
        set clk_period [expr $clk_period - $wc_slack + $jitter_compensation]
        post_message "  Adjusted period: $clk_period ([format %+0.3f [expr -$wc_slack]], $wc_metric)"

        # Compute fmax from clock period. Clock period is in nanoseconds and the
        # fmax number should be in MHz.
        set fmax [expr 1000 / $clk_period]

        if {$fmax_from_summary < $fmax} {
            post_message "  Restricted Fmax from STA is lower than $fmax, using it instead."
            set fmax $fmax_from_summary
        }

        # Truncate to two decimal places. Truncate (not round to nearest) to avoid the
        # very small chance of going over the clock period when doing the computation.
        set fmax [expr floor($fmax * 100) / 100]
        post_message "  Fmax: $fmax"
    } else {
        post_message -type warning "No slack found for clock $clkname - assuming 10 GHz."
        set fmax 10000
    }

    return [list $fmax $clkname]
}

# Returns [fmax1 u_clkdiv2_name fmax2 u_clk_name]
proc get_user_clks_and_fmax {u_clkdiv2_name u_clk_name jitter_compensation} {
    set result [list]

    # Read in the achieved fmax for each clock
    set x [get_fmax_from_report $u_clk_name 0 $jitter_compensation]
    set fmax2 [lindex $x 0]
    set u_clk_name [lindex $x 1]

    # Is the slow clock configurable separately?
    if {$u_clkdiv2_name != ""} {
        # Yes.  What frequency did it achieve?
        set x [get_fmax_from_report $u_clkdiv2_name 1 $jitter_compensation]
        set fmax1 [lindex $x 0]
        set u_clkdiv2_name [lindex $x 1]
    } else {
        # No.  Set the request based on the primary clock.
        set fmax1 [expr $fmax2 / 2.0]
        if {$fmax1 > $::userClocks::u_clkdiv2_fmax} {
            set fmax1 $::userClocks::u_clkdiv2_fmax
        }
    }

    return [list $fmax1 $u_clkdiv2_name $fmax2 $u_clk_name]
}


#************************************************
# Description: Print the HELP info
#************************************************
proc PrintHelp {} {
    puts "Compute user clock frequencies based on the AFU JSON requests and actual frequencies"
    puts "achieved following place and route."
    puts ""
    puts "Usage: quartus_sta -t compute_user_clock_freqs.tcl --project=<project> --revision=<revision>"
}

# Entry point when run as the primary script
proc main {} {
    # Run as the top level script. Open a project.
    if { [::options::ParseCMDArguments {--project --revision}] == -1 } {
        PrintHelp
        return -1
    }

    set project $::options::optionMap(--project)
    set revision $::options::optionMap(--revision)

    project_open -revision $revision $project
    create_timing_netlist
    read_sdc

    if { [compute_uclk $project $revision] } {
        post_message "Updating timing netlist with new user clock frequency."
        read_sdc
        update_timing_netlist
    }

    project_close
}

# Entry point when invoked from another script with a project open
proc from_sta {} {
    set project [get_current_project]
    set revision [get_current_revision]

    post_message "Running OFS user_clock_freqs_compute.tcl" \
        -submsgs [list "Project: ${project}" "Revision: ${revision}"]

    if { [compute_uclk $project $revision] } {
        post_message "Updating timing netlist with new user clock frequency."
        read_sdc
        update_timing_netlist
    }
}

if { [info script] eq $::argv0 } {
    main
} else {
    from_sta
}

