//
// Description
//-----------------------------------------------------------------------------------------------
//
//   Platform top level module
//
//-----------------------------------------------------------------------------------------------

                   `include "fpga_defines.vh"
                   `include "ofs_ip_cfg_db.vh"
                    import   ofs_fim_cfg_pkg::*      ;
                    import   ofs_fim_if_pkg::*       ;
                    import   pcie_ss_axis_pkg::*     ;

`ifdef INCLUDE_HSSI
                   `include  "ofs_fim_eth_plat_defines.svh"
`endif

//-----------------------------------------------------------------------------------------------
// Module ports
//-----------------------------------------------------------------------------------------------

module top 
   import ofs_fim_mem_if_pkg::*;
   import top_cfg_pkg::*;
 `ifdef INCLUDE_HSSI
   import ofs_fim_eth_if_pkg::*;
 `endif
(
   // IA840F BMC SPI master on the board; no PMCI replacement tie-offs.
   input wire bwbmc_fpga_max_mosi,
   input wire bwbmc_fpga_spi_cs,
   input wire bwbmc_fpga_max_sclk,
   inout wire bwbmc_fpga_max_miso,
   output wire bwbmc_bmc_irq,
   output wire bwbmc_bmc_mst_en_n,
                    input                                       SYS_REFCLK,   // System Reference Clock (100MHz)

   // Bank 9A BTI reference is required even with INCLUDE_HSSI disabled.
   input wire qsfp_ref_clk,

// Local Memory technology interfaces
`ifdef INCLUDE_LOCAL_MEM
`ifdef INCLUDE_DDR4
                    ofs_fim_mem_ddr4_ref_clk_if.ip              ddr4_mem_ref_clk  [NUM_DDR4_CHANNELS-1:0],
`ifdef HAS_IFC_MEM_SS_MEM_DDR4_IF
                    mem_ss_mem_ddr4_if.ip                       ddr4_mem          [NUM_GROUP_0_DDR4_CHANNELS-1:0],
`endif
`ifdef HAS_IFC_MEM_SS_MEM_G1_DDR4_IF
                    mem_ss_mem_g1_ddr4_if.ip                    ddr4_mem_group_1  [NUM_GROUP_1_DDR4_CHANNELS-1:0],
`endif
